def _generateRandomName( lsPre, lsMid, lsEnd ) :
	s = ""
	if len( lsPre ) > 0 :
		CvUtil.pyPrint( CvUtil.randomElement( lsPre ) )
		s += CvUtil.randomElement( lsPre )
	if len( lsMid ) > 0 :
		s += CvUtil.randomElement( lsMid )
	if len( lsEnd ) > 0 :
		s += CvUtil.randomElement( lsEnd )
	return string.capwords( s )

def generateRandomDefaultName() :
	return _generateRandomName( _DEFAULT_PRE, _DEFAULT_MID, _DEFAULT_END )

def generateRandomCivilizationName( eCiv ) :
	lsNames = _CIVILIZATION_NAMES.get( gc.getCivilizationInfo( eCiv ).getType(), None )
	CvUtil.pyPrint( "Names for %s: %s" % ( gc.getCivilizationInfo( eCiv ).getType(), lsNames ) )
	if lsNames :
		return CvUtil.randomElement( lsNames )
	return None

def generateRandomRaceName( eRace ) :
	if eRace >= 0 :
		lsNames = _RACE_NAMES.get( gc.getPromotionInfo( eRace ).getType(), None )
		if lsNames :
			return CvUtil.randomElement( lsNames )
	return None

def generateRandomUnitName( pUnit ) :
	# type: (CyUnit) -> unicode
	sName = generateRandomCivilizationName( gc.getPlayer( pUnit.getOwner() ).getCivilizationType() )
	if sName is not None :
		return sName
	sName = generateRandomRaceName( pUnit.getRace() )
	if sName is not None :
		return sName
	return generateRandomDefaultName()
	
